class FormalMethodExecutionRequest(Strict):
    contract: Literal["knowlab/formal-method-execution/v1"]
    run_id: UUID
    owner_subject: str = Field(min_length=1, max_length=512)
    request_id: UUID
    workdraft_id: UUID
    revision: int = Field(ge=1, strict=True)
    method_id: UUID
    # These types are shared with the admission request, never a legacy pack.
    draft: FormalMethodDraft
    dependencies: tuple[MethodRef, ...] = Field(max_length=1000)
    execution: FormalExecutionSpec

    @property
    def runner(self) -> Runner:
        """Lifecycle projection only; the wire keeps execution.runner."""
        return self.execution.runner

    def admission_request(self) -> FormalMethodValidationRequest:
        return FormalMethodValidationRequest.model_validate(
            {
                **self.model_dump(mode="json", by_alias=True, exclude={"execution"}),
                "contract": "knowlab/formal-method-validation/v1",
            }
        )

    def fingerprint(self) -> str:
        return fingerprint(self.model_dump(mode="json", by_alias=True))

    @model_validator(mode="after")
    def supported(self):
        p = self.draft.definition.procedure
        if isinstance(p, ToolProcedure):
            if self.dependencies:
                raise ValueError("Direct trials cannot dispatch other methods")
            if p.implementation.kind in ("skill_instruction", "registered_instruction"):
                if (
                    self.draft.allowed_callers != ("host",)
                    or p.max_model_turns != 1
                    or p.implementation.requirement_ids
                    or self.draft.definition.access_requirements
                    or self.draft.definition.what_requires_approval
                    or any(
                        c.expected.outcome != "succeeded"
                        for c in self.execution.suite.cases
                    )
                ):
                    raise ValueError(
                        "Instruction trials require host-only single-turn output cases "
                        "without tools"
                    )
            elif (
                p.implementation.kind
                not in ("mcp", "skill_script", "registered_script", "service_function")
                or (
                    p.implementation.kind
                    in ("skill_script", "registered_script", "service_function")
                    and self.draft.allowed_callers != ("host",)
                )
                or p.max_model_turns != 0
            ):
                raise ValueError(
                    "Execution supports zero-turn MCP or host-only scripts and service functions"
                )
        else:
            plan = unique_plan(self.draft.definition)
            if self.draft.allowed_callers != ("host",):
                raise ValueError("Unique plan execution supports only the host caller")
            references = {
                (ref.method_id, ref.version, ref.digest)
                for step in plan
                for ref in step.candidates
            }
            supplied = {
                (ref.method_id, ref.version, ref.digest) for ref in self.dependencies
            }
            if len(self.dependencies) != len(references) or supplied != references:
                raise ValueError(
                    "Unique plan dependencies must match every exact candidate"
                )
        callers = set(self.draft.allowed_callers)
        if {c.caller for c in self.execution.suite.cases} != callers or {
            c.caller
            for c in self.execution.suite.cases
            if c.expected.outcome == "succeeded"
        } != callers:
            raise ValueError(
                "Every allowed caller needs its own positive execution case"
            )
        return self


