class FormalMethodExecutionResult(Strict):
    contract: Literal["knowlab/formal-method-execution/v1"]
    run_id: UUID
    request_id: UUID
    method_id: UUID
    request_digest: Digest
    suite: FormalTestSuiteRef
    status: Literal["pending", "running", "waiting", "passed", "failed", "cancelled"]
    admission: FormalMethodValidationResult
    cases: tuple[FormalExecutionCaseResult, ...] = Field(max_length=50)
    spent: str = Field(pattern=r"^[0-9]+(?:\.[0-9]+)?$")
    currency: Literal["CNY"]
    actions: tuple[FormalExecutionAction, ...] = Field(max_length=50)

    @model_validator(mode="after")
    def identity(self):
        if self.admission.run_id != self.run_id:
            raise ValueError("Admission belongs to another execution")
        if len({(c.case_id, c.repetition) for c in self.cases}) != len(self.cases):
            raise ValueError("Duplicate execution case repetition")
        if self.admission.receipt is not None:
            r = self.admission.receipt
            e = r.execution
            if (
                self.status != "passed"
                or e is None
                or e.request_digest != self.request_digest
                or (e.suite_id, e.suite_version, e.suite_digest)
                != (self.suite.suite_id, self.suite.version, self.suite.digest)
                or r.request_id != self.request_id
                or r.method_id != self.method_id
            ):
                raise ValueError("Execution evidence differs from this result")
        if self.status == "passed" and (
            self.admission.receipt is None
            or not self.cases
            or any(
                c.outcome in {"pending", "unknown", "cancelled"}
                or c.status in {"pending", "running", "waiting", "cancelled"}
                for c in self.cases
            )
        ):
            raise ValueError("Passed execution needs complete, known runtime evidence")
        if self.status == "passed":
            assert self.admission.receipt is not None
            evidence = self.admission.receipt.execution
            assert evidence is not None
            callers: set[Caller] = {case.caller for case in self.cases}
            positive = {
                case.caller
                for case in self.cases
                if case.status == "passed" and case.outcome == "succeeded"
            }
            if not evidence.covers_callers(tuple(callers)) or positive != callers:
                raise ValueError(
                    "Execution receipt lacks positive results for every caller"
                )
        return self


def _pointer(value: Any, pointer: str) -> Any:
    for part in pointer.split("/")[1:]:
        key = part.replace("~1", "/").replace("~0", "~")
        if isinstance(value, dict):
            value = value[key]
        elif (
            isinstance(value, list)
            and key.isascii()
            and key.isdecimal()
            and (key == "0" or not key.startswith("0"))
        ):
            value = value[int(key)]
        else:
            raise KeyError(key)
    return value


def evaluate_assertions(
    case: FormalExecutionCase, outputs: dict
) -> tuple[FormalAssertionResult, ...]:
    """Only called by the evaluator after the runtime validates output schemas."""
    results = []
    for index, assertion in enumerate(case.expected.assertions):
        try:
            actual = _pointer(outputs, assertion.pointer)
            if isinstance(assertion, EqualsAssertion):
                passed = fingerprint(actual) == fingerprint(assertion.value)
            elif isinstance(assertion, ApproxAssertion):
                passed = (
                    type(actual) in (int, float)
                    and math.isfinite(actual)
                    and abs(actual - assertion.value) <= assertion.absolute_tolerance
                )
            else:
                passed = isinstance(actual, str) and assertion.value in actual
            detail = "matched" if passed else "value did not match"
        except (KeyError, IndexError, ValueError, TypeError, OverflowError):
            passed, detail = False, "output pointer missing or invalid value"
        results.append(FormalAssertionResult(index=index, passed=passed, detail=detail))
    return tuple(results)
